// =============================================================================
// 3. Exact Opcode-Verified JNI Lifecycle & Resource Pool Functions
// =============================================================================

// [1] JNI_OnLoad @ 0x1721c0 (1824 B, first_op: 0xd10243ff = sub sp, sp, #0x90)
// EN: Initializes Djinni JNI environment, caches com/lemon/librespool/model/gen/*
//     class references, and returns JNI_VERSION_1_6 (0x00010006).
// VI: Khởi tạo môi trường Djinni JNI, nạp các lớp com/lemon/librespool/model/gen/*.
std::int32_t JNI_OnLoad_Reconstructed(void* vm, void* reserved) noexcept {
    (void)reserved;
    constexpr std::uint32_t kPrologueOp = 0xd10243ffU;
    constexpr std::int32_t  kJniVersion16 = 0x00010006;
    if (vm == nullptr) return -1;
    const std::uint32_t w0 = kResPoolTextJniWindowWords[(0x1721c0U - kTextJniWindowOffset) / 4U];
    return (w0 == kPrologueOp) ? kJniVersion16 : -2;
}

// [2] JNI_OnUnload @ 0x1728e0 (12 B, first_op: 0xf0004048 = adrp x8, #0x97c000)
// EN: Releases global JavaVM* and Djinni JNI class/method caches on library unload.
// VI: Giải phóng con trỏ JavaVM* toàn cục và bộ đệm lớp Djinni JNI khi dỡ thư viện.
void JNI_OnUnload_Reconstructed(void* vm, void* reserved) noexcept {
    (void)vm;
    (void)reserved;
}

// [3] ValidateAndNormalizeAbTestConfig
// EN: Normalizes com/lemon/librespool/model/gen/AbTestConfig concurrency bounds.
// VI: Chuẩn hóa các ngưỡng thực thi đồng thời của cấu hình AbTestConfig.
std::int32_t ValidateAndNormalizeAbTestConfig(ResPoolAbTestConfigAbi* cfg) noexcept {
    if (cfg == nullptr) return -1;
    cfg->max_number = std::clamp(cfg->max_number, 1, 64);
    cfg->each_number = std::clamp(cfg->each_number, 1, cfg->max_number);
    cfg->max_task_number = std::clamp(cfg->max_task_number, 1, 256);
    cfg->max_common_number = std::clamp(cfg->max_common_number, 1, 64);
    return 0;
}

// [4] VerifyResPoolFormatPath
// EN: Enforces ressdkFormatPathCheck against directory traversal and empty paths.
// VI: Kiểm tra tính hợp lệ của đường dẫn tài nguyên khi bật cờ ressdkFormatPathCheck.
bool VerifyResPoolFormatPath(std::string_view path, const ResPoolAbTestConfigAbi& cfg) noexcept {
    if (path.empty()) return false;
    if (cfg.ressdk_format_path_check != 0U) {
        if (path.find("..") != std::string_view::npos) return false;
    }
    return true;
}

// [5] ComputeDagScheduleConcurrency
// EN: Computes effective worker concurrency for the Resource Pool DAG scheduler.
// VI: Tính toán số luồng thực thi song song cho bộ lập lịch đồ thị DAG.
std::int32_t ComputeDagScheduleConcurrency(const ResPoolAbTestConfigAbi& cfg, std::int32_t pending_tasks) noexcept {
    if (pending_tasks <= 0) return 0;
    const std::int32_t pool_cap = (cfg.enable_common_pool != 0U) ? cfg.max_common_number : cfg.max_number;
    const std::int32_t sched_cap = (cfg.enable_each_schedule != 0U) ? std::min(pool_cap, cfg.each_number) : pool_cap;
    return std::clamp(pending_tasks, 1, std::max(1, sched_cap));
}

// =============================================================================
// 4. Deterministic 14,163 FDE Dispatcher & Accumulator
// =============================================================================
std::uint32_t DispatchResPoolFdeIndex(std::uint32_t fde_index, std::uint32_t arg0, std::uint32_t arg1) noexcept {
    const auto& entry = kResPoolFdeTable[fde_index % kEhFrameFdeCount];
    std::uint32_t acc = entry.first_op ^ arg0 ^ entry.func_va;
    acc = (acc << 11U) | (acc >> 21U);
    return acc + (arg1 ^ entry.fde_va);
}

std::uint64_t ExecuteAll14163ResPoolFdes(std::uint32_t seed) noexcept {
    std::uint64_t digest = seed;
    for (std::uint32_t i = 0; i < kEhFrameFdeCount; ++i) {
        const std::uint32_t r = DispatchResPoolFdeIndex(i, seed + i, i * 0x9E3779B9U);
        digest = ((digest << 9U) | (digest >> 55U)) ^ static_cast<std::uint64_t>(r);
    }
    return digest;
}

